//! The web features each Version Profile's TVs have, from Samsung's TV web
//! engine specifications (`data/web_features.toml`, generated by
//! `data/web-features.py`). The Engine runs the milestone those TVs ship, but
//! the page lists features those TVs lack that the Engine has (measured,
//! #106), so the Shims delete what an App would reach of them (see
//! shims/src/features.ts).

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::sync::OnceLock;

/// A row's cell for one Version Profile.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Support {
    Yes,
    /// "Yes (partially)".
    Partial,
    /// "Yes (basic support)".
    Basic,
    No,
}

#[derive(Debug, Clone, Deserialize)]
struct WebFeature {
    name: String,
    support: BTreeMap<String, Support>,
    /// What the App reaches of the feature, as paths from `window`.
    #[serde(default)]
    remove: Vec<String>,
    /// Why the row is ambiguous; such rows aren't applied.
    unverified: Option<String>,
}

/// A feature the Shims delete, and what of it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct RemovedFeature {
    pub name: String,
    pub paths: Vec<String>,
}

#[derive(Debug, Deserialize)]
pub struct WebFeatureCatalog {
    #[serde(rename = "feature", default)]
    features: Vec<WebFeature>,
}

impl WebFeatureCatalog {
    pub fn parse(toml: &str) -> Result<WebFeatureCatalog, toml::de::Error> {
        toml::from_str(toml)
    }

    /// The catalog bundled with the simulator.
    pub fn bundled() -> &'static WebFeatureCatalog {
        static CATALOG: OnceLock<WebFeatureCatalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            WebFeatureCatalog::parse(include_str!("../data/web_features.toml"))
                .expect("bundled web_features.toml is valid")
        })
    }

    /// Whether the page says Tizen `version`'s TVs lack the feature `name`,
    /// ambiguous or not.
    pub fn lacks(&self, version: &str, name: &str) -> bool {
        self.features.iter().any(|feature| {
            feature.name == name && feature.support.get(version) == Some(&Support::No)
        })
    }

    /// The features Tizen `version`'s TVs lack that the Shims can delete.
    pub fn removed_on(&self, version: &str) -> Vec<RemovedFeature> {
        self.features
            .iter()
            .filter(|feature| {
                feature.support.get(version) == Some(&Support::No)
                    && feature.unverified.is_none()
                    && !feature.remove.is_empty()
            })
            .map(|feature| RemovedFeature {
                name: feature.name.clone(),
                paths: feature.remove.clone(),
            })
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn catalog() -> WebFeatureCatalog {
        WebFeatureCatalog::parse(
            r#"
            [[feature]]
            name = "Geolocation API"
            source = "TV specifications/web-engine-specifications.html, Device table"
            support = { "4.0" = "no", "5.0" = "yes" }
            remove = ["Navigator.prototype.geolocation", "Geolocation"]

            [[feature]]
            name = "Custom Elements"
            source = "TV specifications/web-engine-specifications.html, Web Components table"
            support = { "4.0" = "yes", "6.5" = "no" }
            remove = ["customElements"]
            unverified = "The row doesn't say which version."

            [[feature]]
            name = "Classes"
            source = "TV specifications/web-engine-specifications.html, JavaScript (ES6) table"
            support = { "3.0" = "no", "4.0" = "yes" }
            "#,
        )
        .unwrap()
    }

    fn removed(catalog: &WebFeatureCatalog, version: &str) -> Vec<String> {
        catalog
            .removed_on(version)
            .into_iter()
            .map(|feature| feature.name)
            .collect()
    }

    #[test]
    fn a_feature_is_removed_where_the_tvs_lack_it() {
        let catalog = catalog();
        assert_eq!(
            catalog.removed_on("4.0"),
            [RemovedFeature {
                name: "Geolocation API".into(),
                paths: vec![
                    "Navigator.prototype.geolocation".into(),
                    "Geolocation".into()
                ],
            }]
        );
        assert!(removed(&catalog, "5.0").is_empty());
    }

    #[test]
    fn the_bundled_catalog_follows_the_page() {
        let catalog = WebFeatureCatalog::bundled();
        // The removable rows that are No in the page's Tizen 4.0 (2018) column.
        assert_eq!(
            removed(catalog, "4.0"),
            [
                "Array.prototype.copyWithin() method",
                "Proxy objects",
                "Reflect object",
                "Geolocation API",
                "Audio Output Devices API",
                "Intersection Observer API",
                "WebRTC API",
                "autocapitalize attribute",
                "MouseEvent.buttons property",
                "WebVR API",
            ]
        );
        assert!(!removed(catalog, "5.0").contains(&"Geolocation API".to_string()));
    }

    #[test]
    fn the_bundled_catalog_covers_every_version_profile() {
        let catalog = WebFeatureCatalog::bundled();
        for profile in crate::profile::VersionProfile::all() {
            for feature in &catalog.features {
                assert!(
                    feature.support.contains_key(&profile.version),
                    "`{}` has no cell for Tizen {}",
                    feature.name,
                    profile.version
                );
            }
        }
    }

    #[test]
    fn ambiguous_rows_are_not_applied() {
        assert!(removed(&catalog(), "6.5").is_empty());
    }

    #[test]
    fn features_with_nothing_to_delete_are_not_listed() {
        // Syntax can't be deleted from the page.
        assert!(removed(&catalog(), "3.0").is_empty());
    }
}
